"""art.eight.library: the generated object-eight rows and their atlas pages (object-eight-library.ts, generated by import-object-eight.mjs), described."""
from fractal.holon import Fn, Holon

HOLON = Holon(
    id="art.eight.library", rung=3, title="Object-eight rows",
    purpose="Append the eight-view object pictures and their pages to the library, rows kept append-only.",
    requires=[
        "OBJECT_EIGHT_SETS is the existing sets then the native sets; appendObjectEight adds their rows (object-eight-library.ts lines 46 and 51).",
        "The file is generated: rows are append-only so saved indices stay valid (its header).",
    ],
    owns=["OBJECT_EIGHT_SETS", "the object-eight atlas page URLs"],
    files=["src/game/object-eight-library.ts"],
    dynamics=[
        Fn(name="OBJECT_EIGHT_SETS", at="src/game/object-eight-library.ts:46", does="the eight-view sets: existing then native", sig="OBJECT_EIGHT_SETS"),
        Fn(name="appendObjectEight", at="src/game/object-eight-library.ts:51", does="appends the object-eight rows and pages to LIBRARY", sig="appendObjectEight(library, pages)"),
    ],
    inputs=["the generated sets (import-object-eight.mjs)"],
    outputs=["object-eight rows in LIBRARY"],
    tests=["tests/object-eight.test.ts", "tests/eight-lot-views.test.ts", "tests/tournament-kit.test.ts"],
    below=["art.eight.types", "art.eight.existing"], above=["art.eight.registry"],
    dual="MISSING: an appended object-eight row cannot be removed (the file is generated and append-only)",
    impl="describe",
)
